architecture.h4_f:
|
msg = CBOR{v:1, मजकूर, reply_to, send_at}
ct = AES-GCM-256-एनक्रिप्ट(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
|
pt = CBOR{v:1, मजकूर, reply_to?, thread_id?, उल्लेख?, sent_at}
ct = AES-GCM-256-एनक्रिप्ट(room_key, nonce, pt, aad=hex(room_id))
वायर = CBOR{
  v: 1,
  सिफरटेक्स्ट: hex(ct), // चल लांबी
  nonce: hex(12 B),
  प्रेषक_स्यूडो: हेक्स(१६ बी),
  send_at: unix_ms
}

cryptoWire.h5_f:
|
बाह्य = CBOR{
  source_node: hex32,
  लक्ष्य_वापरकर्ता: int64,
  inner_ciphertext: बाइट्स,
  inner_nonce: बाइट्स,
  send_at: unix_ms
}
sig = Ed25519-साइन(स्रोत_प्रिव्ह, बाह्य)
POST /फेडरेशन/डिलिव्हर { लिफाफा: बाह्य, चिन्ह: hex64 }

auth.h1_f:
|
POST /api/authentication/register
  { वापरकर्तानाव, पासवर्ड, x25519_public_key, display_name, phone?, email?, avatar_emoji }

प्रतिसाद 201 तयार केला:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token पेलोड:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15min }
refresh_token पेलोड:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256 .env कडून नोडच्या 64-बाइट गुप्त सह स्वाक्षरी

auth.h7_f:
|
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR पेलोड = { nonce, user_id, सर्व्हर: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → नवीन उपकरण नोंदणीकृत; JWTs परत आले.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 हेक्स
सिफरटेक्स्ट = AES-GCM-एनक्रिप्ट(room_key, nonce, CBOR_payload, aad=room_id)

फॅन-आउट फ्रेम: { type:"m", रूम, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
|
init POST /api/files/resumable/init {फाइलनाव, आकार, chunk_size_hint}
            ← {upload_id, chunk_size}
भाग PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← २०४
अंतिम करा POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL अपूर्ण: 24 तास

presence.h1_f:
|
क्लायंट: पहिल्या कीस्ट्रोकवर → पाठवा {type:"t", state:"start"}
         स्थिती बदलल्याशिवाय आणखी 3 s साठी पाठवणार नाही
         शेवटच्या कीस्ट्रोकनंतर 10 सेकंद → पाठवा {प्रकार:"t", स्थिती:"stop"}
रिसीव्हर: शेवटच्या "प्रारंभ" नंतर 10 s स्वयं-थांबवा जर "थांबा" आला नाही

calls.h1_f:
|
POST /api/calls/{room_id}/start {व्हिडिओ, ऑडिओ} → call_id
WS प्रसारण {type:"c", kind:"invite", call_id}
WS प्रसारण {प्रकार:"c", प्रकार:"ऑफर", sdp}
WS प्रसारण {प्रकार:"c", प्रकार:"उत्तर", sdp}
WS प्रसारण {प्रकार:"c", प्रकार:"उमेदवार", बर्फ} × N
POST /api/calls/{call_id}/end

federation.h2_f:
लिफाफा = {
  source_node : hex32,
  लक्ष्य_वापरकर्ता : int64,
  inner_ciphertext: बाइट्स,
  inner_nonce : बाइट्स,
  send_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(लिफाफा))
POST /फेडरेशन/डिलिव्हर { लिफाफा, हस्ताक्षर }

push.h4_f:
|
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
वेब SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
|
साधन = चिन्ह_साधन
इनपुट = स्त्रोत वृक्ष, की/release.key
प्रकट = {
  आवृत्ती: "0.1.0",
  बिल्ट_एट: युनिक्स_एमएस,
  फाइल्स: [{path, sha256, आकार}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(मनीफेस्ट))
आउटपुट = INTEGRITY.sig.json = {मनीफेस्ट, साइन केलेले_बाय: pub_hex, sig: sig_hex}

bots.h1_f:
|
तयार करा: POST /api/bots {वापरकर्तानाव, display_name, code}
          → {bot_id, टोकन, पबकी}
रन: इन-प्रोसेस (नोडच्या आत कोरटीन)
      OR बाह्य (लाँग-पोल /api/bots/{id}/updates, टोकन-auth'd)
संदेश: {मजकूर, स्वाक्षरी: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
|
वर /प्रारंभ {
  "स्वागत आहे, {ctx.first_name}" सोडा
}
वर /add <item> {
  state.list = (state.list किंवा []) + [ctx.args.item]
  emit "जोडले: {ctx.args.item}"
}

security.h4_f:
|
canary.txt (दररोज):
  {तारीख, चिन्ह: Ed25519-Sign(release_priv, date)}
क्लायंट सत्यापित करतो → अनुपस्थित किंवा अवैध ⇒ तडजोड संशयित

आणीबाणी:
  प्रशासन POST /api/admin/revoke-all {कारण}
  नोड प्रसारण {प्रकार:"n", कार्यक्रम:"तडजोड", कारण}
  क्लायंट की पुसतात, री-बूटस्ट्रॅप सक्ती करतात

debugging.h2_f:
|
रेट हिस्टोग्राम (प्रति मार्ग + पद्धत):
  vortex_http_requests_total{मार्ग,पद्धत,स्थिती}
  vortex_http_request_duration_seconds_bucket{मार्ग,पद्धत,le}

वेबसॉकेट गेज:
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{room,user}

सानुकूल काउंटर:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{प्रकार}

